function App() {
  const [ssr, setSsr] = useState(false);
  const [isr, setIsr] = useState(false);
  const needsServer = ssr || isr;
  const target = needsServer
    ? 'Server target: Vercel or self-hosted Node (standalone/Docker)'
    : 'Static export: out/ folder on any CDN (S3, Pages, Nginx)';
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>Pick a deployment target</h3>
      <label><input type="checkbox" checked={ssr} onChange={e => setSsr(e.target.checked)} /> Uses SSR / route handlers</label><br/>
      <label><input type="checkbox" checked={isr} onChange={e => setIsr(e.target.checked)} /> Uses ISR / Image Optimization</label>
      <p style={{ marginTop: 12, fontWeight: 600 }}>{target}</p>
    </div>
  );
}

