solution.code:
// Option A — keep server features: remove output:'export', deploy a Node server (Vercel/self-host).
// Option B — stay static: remove server bits and configure images:
//   next.config.js -> { output: 'export', images: { unoptimized: true } }
function App() {
  // Now every page is prerendered to static HTML; no route handlers/SSR/ISR.
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>Static export builds cleanly</h3>
      <p>Server features removed (or moved to a server target). Images use unoptimized / a custom loader.</p>
    </div>
  );
}
